// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // fuzzed params: from, caddress (we'll pass a helper deployed below), and a uint v
    // we will always construct a single-element address[] for _tos to target the mutant's changed require
    function testFuzz_property(address from, address dummy, uint256 v) public {
        // keep addresses non-zero to be in wide admissible domain
        vm.assume(from != address(0));
        // dummy may be any address, but we will use a deployed recorder/handler below

        // Deploy a Recording helper that exposes the exact transferFrom signature the contract calls
        Recorder rec = new Recorder();

        // Prepare single-element recipients array (this is the deciding factor)
        address[] memory tos = new address[](1);
        tos[0] = address(rec);

        // The general rule: for any inputs (including this fuzzed from and v), calling transfer with a single-element _tos MUST NOT revert in the reference implementation.
        // So we call and catch revert: reference should complete and set ok=true. The mutant (which requires _tos.length>1) will revert for this input.

        bool ok;
        try c.transfer(from, address(rec), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // Assert the reference property: the call must succeed for all admissible inputs (single-element _tos arrays).
        // This will PASS on the reference and FAIL on the mutant for some inputs (specifically this single-element case).
        assertTrue(ok);
    }
}

// Recording helper that exposes the exact signature transferFrom(address,address,uint256)
contract Recorder {
    // record number of calls and last parameters
    uint256 public calls;
    address public lastFrom;
    address public lastTo;
    uint256 public lastV;

    // The contract C encodes calls with selector of transferFrom(address,address,uint256)
    // Declare that function so ABI decoding happens and we can record arguments.
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        calls += 1;
        lastFrom = from;
        lastTo = to;
        lastV = v;
        return true; // succeed to match reference behavior
    }
}
